mapper.update:
UPDATE daily_chat_summary_states
SET status = 'FAILED',
    claim_token = NULL,
    claimed_at = NULL,
    retry_count = retry_count + 1,
    next_retry_at = #{nextRetryAt},
    failure_code = #{failureCode},
    updated_at = NOW()
WHERE user_id = #{userId}
  AND summary_date = #{summaryDate}
  AND claim_token = #{claimToken}
  AND source_version = #{sourceVersion}

UPDATE daily_chat_summary_states
SET status = 'STALE',
    claim_token = NULL,
    claimed_at = NULL,
    updated_at = NOW()
WHERE user_id = #{userId}
  AND summary_date = #{summaryDate}
  AND claim_token = #{claimToken}
  AND source_version <> #{sourceVersion}
